<?php
require __DIR__.'/ui.php';auth();$p=db();$id=(int)($_GET['id']??0);$s=$p->prepare("SELECT o.*,c.name customer,u.name seller FROM orders o LEFT JOIN customers c ON c.id=o.customer_id LEFT JOIN users u ON u.id=o.seller_id WHERE o.id=?");$s->execute([$id]);$o=$s->fetch();if(!$o)exit('Pedido não encontrado.');$token=ensure_order_token($id);$portalUrl=public_order_url($token);
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();if(isset($_POST['update_status'])){$p->prepare("UPDATE orders SET status=?,production_stage=?,art_status=? WHERE id=?")->execute([$_POST['status'],$_POST['production_stage'],$_POST['art_status'],$id]);$p->prepare("INSERT INTO artwork_history(order_id,status,notes,user_id)VALUES(?,?,?,?)")->execute([$id,$_POST['art_status'],$_POST['art_notes'],current_user()['id']]);timeline_event($id,'status','Fluxo atualizado','Status: '.$_POST['status'].' | Produção: '.$_POST['production_stage'].' | Arte: '.$_POST['art_status']);audit('update','orders',$id);go('order.php?id='.$id);}if(isset($_POST['upload'])){try{$path=upload_file($_FILES['file'],$id);if($path){$p->prepare("INSERT INTO order_files(order_id,file_path,original_name,file_type,uploaded_by)VALUES(?,?,?,?,?)")->execute([$id,$path,$_FILES['file']['name'],$_FILES['file']['type'],current_user()['id']]);flash('success','Arquivo anexado.');}}catch(Throwable $e){flash('error',$e->getMessage());}go('order.php?id='.$id);}}
$s=$p->prepare("SELECT * FROM order_items WHERE order_id=?");$s->execute([$id]);$items=$s->fetchAll();$s=$p->prepare("SELECT * FROM order_files WHERE order_id=? ORDER BY id DESC");$s->execute([$id]);$files=$s->fetchAll();page_head('Pedido '.$o['number']);?>
<div class="grid g2"><div class="card"><h2>Resumo</h2><p>Cliente: <b><?=e($o['customer']?:'Consumidor')?></b></p><p>Vendedor: <?=e($o['seller']?:'-')?></p><p>Total: <b><?=money($o['total'])?></b> • Lucro: <?=money($o['profit'])?></p><p>Entrega: <?=e($o['delivery_date'])?> <?=e($o['delivery_time'])?> • <?=e($o['recipient_name'])?></p><p>Endereço: <?=e($o['delivery_address'])?></p><p>Observações: <?=nl2br(e($o['notes']))?></p><div class="actions"><a class="btn" target="_blank" href="<?=e($portalUrl)?>">Portal do cliente</a><a class="btn" href="timeline.php?order_id=<?=$id?>">Timeline</a><?php if($o['recipient_phone']):$msg=template_message('order_received',['cliente'=>$o['customer']?:$o['recipient_name'],'pedido'=>$o['number'],'total'=>money($o['total']),'portal'=>$portalUrl]);?><a class="btn green" target="_blank" href="<?=e(whatsapp_link($o['recipient_phone'],$msg))?>">WhatsApp</a><?php endif;?></div><div id="qrcode" data-url="<?=e($portalUrl)?>" style="margin-top:12px"></div></div>
<div class="card"><h2>Fluxo do pedido</h2><form method="post"><?=csrf_field()?><input type="hidden" name="update_status" value="1"><label>Status geral</label><select name="status"><?php foreach(['Recebido','Em produção','Pronto','Em rota','Entregue','Cancelado'] as $st):?><option <?=$o['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select><label>Etapa de produção</label><select name="production_stage"><?php foreach(['Novo','Arte pendente','Aguardando cliente','Separação','Montagem','Personalização','Conferência','Pronto'] as $st):?><option <?=$o['production_stage']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select><label>Status da arte</label><select name="art_status"><?php foreach(['Não se aplica','Aguardando arte','Enviada ao cliente','Alteração solicitada','Aprovada','Reprovada'] as $st):?><option <?=$o['art_status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select><label>Observação da arte</label><textarea name="art_notes"></textarea><button class="primary">Atualizar</button></form></div></div>
<div class="card"><h2>Itens / personalização</h2><div class="table"><table><tr><th>Produto</th><th>Qtd.</th><th>Personalização</th><th>Texto</th><th>Detalhes</th></tr><?php foreach($items as $i):?><tr><td><?=e($i['product_name'])?></td><td><?=$i['qty']?></td><td><?=e($i['customization'])?></td><td><?=e($i['personalized_text'])?></td><td><?=e($i['details'])?></td></tr><?php endforeach;?></table></div></div>
<div class="grid g2"><div class="card"><h2>Anexar arte / referência</h2><form method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="upload" value="1"><input type="file" name="file" accept=".jpg,.jpeg,.png,.webp,.pdf" required><p>JPG, PNG, WEBP ou PDF, até 8 MB.</p><button class="primary">Anexar</button></form></div><div class="card"><h2>Arquivos</h2><?php foreach($files as $f):?><p><?=e($f['original_name'])?> <small><?=e($f['created_at'])?></small></p><?php endforeach;?></div></div><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>const q=document.getElementById('qrcode');if(q&&window.QRCode)new QRCode(q,{text:q.dataset.url,width:128,height:128});</script><?php page_foot();?>